package com.rustyledger.core;

import java.math.BigDecimal;

public class Account {
    public final String id;
    public final String tier;
    public final String currency;
    public BigDecimal balance;

    public Account(String id, String tier, String currency, BigDecimal balance) {
        this.id = id;
        this.tier = tier;
        this.currency = currency;
        this.balance = balance.setScale(2);
    }
}

package com.rustyledger.core;

import java.util.ArrayList;
import java.util.List;

public class AuditLog {
    private final List<String> audit = new ArrayList<>();
    private int auditSeq = 0;

    public void record(String verb, String date, String outcome) {
        auditSeq++;
        audit.add(String.format("%03d  %s %s %s", auditSeq, verb, date, outcome));
    }

    public List<String> getLog() {
        return new ArrayList<>(audit);
    }
}

package com.rustyledger.core;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class Exchange {
    public static BigDecimal rate(String currency) {
        return switch (currency) {
            case "EUR" -> new BigDecimal("4.30");
            case "USD" -> new BigDecimal("4.00");
            default -> new BigDecimal("1.00");
        };
    }

    public static BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger.core;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class Fees {
    public static BigDecimal calculateTransfer(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        }
        if ("PREMIUM".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00").setScale(2);
    }

    public static BigDecimal calculateWithdraw(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00").setScale(2) : new BigDecimal("0.00").setScale(2);
    }
}

package com.rustyledger.core;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class Limits {
    private final Map<String, BigDecimal> used = new HashMap<>();

    public String check(String date, Account a, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit = switch (a.tier) {
            case "STANDARD" -> new BigDecimal("5000.00");
            case "PREMIUM" -> new BigDecimal("20000.00");
            default -> new BigDecimal("50000.00");
        };
        if (getUsed(a.id, date).add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit.setScale(2) + " for " + a.tier;
        }
        BigDecimal overdraft = "PREMIUM".equals(a.tier) ? new BigDecimal("500.00") : BigDecimal.ZERO;
        BigDecimal needed = amount.add(fee);
        if (a.balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + ", needed " + 
                needed.setScale(2) + " " + a.currency;
        }
        return null;
    }

    public void consume(String id, String date, BigDecimal amount) {
        used.put(id + "|" + date, getUsed(id, date).add(amount));
    }

    private BigDecimal getUsed(String id, String date) {
        return used.getOrDefault(id + "|" + date, BigDecimal.ZERO);
    }
}

package com.rustyledger.core;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Reporting {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        counts.computeIfAbsent(date, k -> new int[2])[slot]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(currency, m.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }

    public String dailyReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        String feeText = formatFees(fees.get(date));
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }

    private String formatFees(Map<String, BigDecimal> f) {
        if (f == null || f.isEmpty()) return "none";
        List<String> parts = new ArrayList<>();
        f.forEach((cur, val) -> parts.add(val.setScale(2).toString() + " " + cur));
        return String.join(", ", parts);
    }
}

