package com.rustyledger.core;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class LedgerImpl implements Ledger {
    private final Map<String, Account> accounts = new HashMap<>();
    private final AuditLog audit = new AuditLog();
    private final Reporting reporting = new Reporting();
    private final TxHistory history = new TxHistory();
    private final Limits limits = new Limits();

    public void openAccount(String id, String tier, String cur, String bal) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) 
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!List.of("STANDARD", "PREMIUM", "STAFF").contains(tier))
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!List.of("PLN", "EUR", "USD").contains(cur))
            throw new IllegalArgumentException("INVALID CURRENCY: " + cur);
        if (bal == null || !bal.matches("\\d+(\\.\\d{1,2})?"))
            throw new IllegalArgumentException("INVALID AMOUNT: " + bal);
        if (accounts.containsKey(id)) 
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accounts.put(id, new Account(id, tier, cur, new BigDecimal(bal)));
    }

    public String balance(String id) {
        Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance + " " + a.currency;
    }

    public List<String> auditLog() { return audit.getLog(); }
    public String dailyReport(String date) { return reporting.dailyReport(date); }

    public String submit(String line) {
        if (line == null || line.trim().isEmpty())
            return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        Integer want = Map.of("TRANSFER", 6, "WITHDRAW", 4, "DEPOSIT", 4, "REVERSE", 3).get(verb);
        if (want == null) return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != want) 
            return reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return reject(verb, null, "BAD_DATE", date);
        if (verb.equals("REVERSE")) return doReverse(date, f[2]);
        return processFinancial(verb, date, f);
    }

    private String processFinancial(String verb, String date, String[] f) {
        String amtText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amtText.matches("\\d+(\\.\\d{1,2})?")) return reject(verb, date, "BAD_AMOUNT", amtText);
        BigDecimal amount = new BigDecimal(amtText).setScale(2);
        if (amount.signum() <= 0) return reject(verb, date, "BAD_AMOUNT", amtText);
        return switch (verb) {
            case "TRANSFER" -> doTransfer(date, f[2], f[3], amount, f[5]);
            case "WITHDRAW" -> doWithdraw(date, f[2], amount);
            default -> doDeposit(date, f[2], amount);
        };
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amt, String cur) {
        Account from = accounts.get(fromId), to = accounts.get(toId);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(cur)) return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.currency);
        BigDecimal fee = Fees.calculateTransfer(from.tier, amt);
        String err = limits.check(date, from, amt, fee);
        if (err != null) return reject("TRANSFER", date, err.split(": ")[0], err.split(": ")[1]);
        BigDecimal credited = from.currency.equals(to.currency) ? amt : Exchange.convert(amt, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amt.add(fee));
        to.balance = to.balance.add(credited);
        limits.consume(fromId, date, amt);
        String txId = history.nextId();
        history.store(txId, new String[]{"TRANSFER", date, fromId, toId, amt.toString(), from.currency, fee.toString(), credited.toString(), "N"});
        reporting.addFee(date, from.currency, fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.currency);
    }

    private String doWithdraw(String date, String id, BigDecimal amt) {
        Account a = accounts.get(id);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = Fees.calculateWithdraw(a.tier);
        String err = limits.check(date, a, amt, fee);
        if (err != null) return reject("WITHDRAW", date, err.split(": ")[0], err.split(": ")[1]);
        a.balance = a.balance.subtract(amt.add(fee));
        limits.consume(id, date, amt);
        String txId = history.nextId();
        history.store(txId, new String[]{"WITHDRAW", date, id, "", amt.toString(), a.currency, fee.toString(), amt.toString(), "N"});
        reporting.addFee(date, a.currency, fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.currency);
    }

    private String doDeposit(String date, String id, BigDecimal amt) {
        Account a = accounts.get(id);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        a.balance = a.balance.add(amt);
        String txId = history.nextId();
        history.store(txId, new String[]{"DEPOSIT", date, id, "", amt.toString(), a.currency, "0.00", amt.toString(), "N"});
        return accept("DEPOSIT", date, txId, "fee=0.00 " + a.currency);
    }

    private String doReverse(String date, String txId) {
        String[] tx = history.get(txId);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", txId);
        if (!"TRANSFER".equals(tx[0])) return reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx[0]);
        if ("Y".equals(tx[8])) return reject("REVERSE", date, "ALREADY_REVERSED", txId);
        if (!tx[1].equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx[1]);
        Account from = accounts.get(tx[2]), to = accounts.get(tx[3]);
        BigDecimal fee = new BigDecimal(tx[6]);
        to.balance = to.balance.subtract(new BigDecimal(tx[7]));
        BigDecimal back = new BigDecimal(tx[4]);
        if ("PREMIUM".equals(from.tier)) {
            back = back.add(fee);
            reporting.addFee(date, from.currency, fee.negate());
        }
        from.balance = from.balance.add(back);
        tx[8] = "Y";
        String newId = history.nextId();
        history.store(newId, new String[]{"REVERSE", date, tx[2], tx[3], tx[4], tx[5], "0.00", tx[7], "Y"});
        return accept("REVERSE", date, newId, "reversed " + txId);
    }

    private String accept(String verb, String date, String txId, String extra) {
        reporting.count(date, 0);
        audit.record(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private String reject(String verb, String date, String code, String message) {
        if (date != null) reporting.count(date, 1);
        audit.record(verb, date == null ? "????-??-??" : date, "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }
}

